IMMUTABLE = (
    "industry_taxonomy",
    "profile_snapshots",
    "usage_ledger",
    "prediction_requests",
    "report_build_inputs",
    "user_report_versions",
    "report_version_forecasts",
    "personal_impacts",
    "recommendations",
    "recommendation_feedback",
    "local_email_deliveries",
    "report_catalog_entries",
    "user_entitlements",
)


def _guards(create: bool) -> None:
    pg = op.get_bind().dialect.name == "postgresql"
    for table in IMMUTABLE:
        if pg:
            if create:
                op.execute(
                    f"CREATE TRIGGER m4_immutable BEFORE UPDATE OR DELETE ON {table} "
                    "FOR EACH ROW EXECUTE FUNCTION futureos_m2_immutable()"
                )
            else:
                op.execute(f"DROP TRIGGER m4_immutable ON {table}")
        else:
            for action in ("update", "delete"):
                if create:
                    op.execute(
                        f"CREATE TRIGGER m4_{table}_{action} BEFORE {action} ON {table} "
                        "BEGIN SELECT RAISE(ABORT,'M4_APPEND_ONLY'); END"
                    )
                else:
                    op.execute(f"DROP TRIGGER m4_{table}_{action}")
    if not create:
        if pg:
            op.execute("DROP TRIGGER m4_reservation_state ON entitlement_reservations")
            op.execute("DROP TRIGGER m4_report_pointer ON user_reports")
            op.execute("DROP FUNCTION futureos_m4_reservation()")
            op.execute("DROP FUNCTION futureos_m4_report_pointer()")
        else:
            for name in (
                "m4_reservation_update",
                "m4_reservation_delete",
                "m4_report_update",
                "m4_report_delete",
            ):
                op.execute("DROP TRIGGER " + name)
        return
    if pg:
        op.execute("""CREATE FUNCTION futureos_m4_reservation() RETURNS trigger
        LANGUAGE plpgsql AS $$ BEGIN
          IF TG_OP='DELETE' THEN RAISE EXCEPTION 'M4_RESERVATION_IMMUTABLE'; END IF;
          IF OLD.state<>'reserved' OR NEW.state NOT IN ('consumed','released')
            OR (to_jsonb(NEW)-'state')<>(to_jsonb(OLD)-'state')
          THEN RAISE EXCEPTION 'M4_RESERVATION_TRANSITION_INVALID'; END IF;
          RETURN NEW;
        END; $$""")
        op.execute(
            "CREATE TRIGGER m4_reservation_state BEFORE UPDATE OR DELETE "
            "ON entitlement_reservations FOR EACH ROW EXECUTE FUNCTION futureos_m4_reservation()"
        )
        op.execute("""CREATE FUNCTION futureos_m4_report_pointer() RETURNS trigger
        LANGUAGE plpgsql AS $$ BEGIN
          IF TG_OP='DELETE' THEN RAISE EXCEPTION 'M4_REPORT_IMMUTABLE'; END IF;
          IF (to_jsonb(NEW)-'current_version_id')<>(to_jsonb(OLD)-'current_version_id')
            OR NOT EXISTS (SELECT 1 FROM user_report_versions v
              WHERE v.id=NEW.current_version_id AND v.report_id=NEW.id AND v.user_id=NEW.user_id
                        AND v.version_num=(SELECT max(version_num) FROM user_report_versions
            WHERE report_id=NEW.id))
          THEN RAISE EXCEPTION 'M4_INVALID_REPORT_POINTER'; END IF;
          RETURN NEW;
        END; $$""")
        op.execute(
            "CREATE TRIGGER m4_report_pointer BEFORE UPDATE OR DELETE ON user_reports "
            "FOR EACH ROW EXECUTE FUNCTION futureos_m4_report_pointer()"
        )
    else:
        op.execute("""CREATE TRIGGER m4_reservation_update BEFORE UPDATE ON entitlement_reservations
        WHEN OLD.state<>'reserved' OR NEW.state NOT IN ('consumed','released')
          OR NEW.id<>OLD.id OR NEW.user_id<>OLD.user_id OR NEW.job_id<>OLD.job_id
                    OR NEW.units<>OLD.units OR NEW.expires_at<>OLD.expires_at OR
            NEW.created_at<>OLD.created_at
        BEGIN SELECT RAISE(ABORT,'M4_RESERVATION_TRANSITION_INVALID'); END""")
        op.execute(
            "CREATE TRIGGER m4_reservation_delete BEFORE DELETE ON entitlement_reservations "
            "BEGIN SELECT RAISE(ABORT,'M4_RESERVATION_IMMUTABLE'); END"
        )
        op.execute("""CREATE TRIGGER m4_report_update BEFORE UPDATE ON user_reports
        WHEN NEW.id<>OLD.id OR NEW.user_id<>OLD.user_id OR NEW.created_at<>OLD.created_at
          OR NOT EXISTS (SELECT 1 FROM user_report_versions v
            WHERE v.id=NEW.current_version_id AND v.report_id=NEW.id AND v.user_id=NEW.user_id
                      AND v.version_num=(SELECT max(version_num) FROM user_report_versions WHERE
            report_id=NEW.id))
        BEGIN SELECT RAISE(ABORT,'M4_INVALID_REPORT_POINTER'); END""")
        op.execute(
            "CREATE TRIGGER m4_report_delete BEFORE DELETE ON user_reports "
            "BEGIN SELECT RAISE(ABORT,'M4_REPORT_IMMUTABLE'); END"
        )
